public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String bufferStr = scanner.next();
        int len = bufferStr.length();
        StringBuilder sb = new StringBuilder(bufferStr);

        for (int index = 0; index < len; index++) {
            if (index != 0 && index != (len - 3)) {
                if (sb.charAt(index) == 'd') {
                    index++;
                    if (index < len && sb.charAt(index) == 'o') {
                        index++;
                        if (index < len && sb.charAt(index) == 't') {
                            sb.setCharAt(index - 2, '.');
                        }
                        index--;
                    }
                    index--;
                }
            }
        }

        int atPosition = 0;
        for (int index = 0; index < len; index++) {
            if (index != 0 && index != (len - 2)) {
                if (sb.charAt(index) == 'a') {
                    index++;
                    if (index < len && sb.charAt(index) == 't') {
                        sb.setCharAt(index - 1, '@');
                        atPosition = 1;
                        break;
                    }
                    index--;
                }
            }
            if (atPosition == 1) break;
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < len; i++) {
            output.append(sb.charAt(i));
